def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        n = int(input_data)
    except ValueError:
        return

    if n == 2:
        print(1)
        print(2)
        return
    elif n == 3:
        print(1)
        print(3)
        return

    # For n >= 4, we can always use as many 2s as possible.
    # If n is even: all 2s.
    # If n is odd: (n-3) is even, so use (n-3)/2 twos and one 3.
    if n % 2 == 0:
        k = n // 2
        primes = [2] * k
    else:
        k = (n - 3) // 2 + 1
        primes = [2] * ((n - 3) // 2) + [3]

    print(k)
    print(*(primes))

if __name__ == "__main__":
    solve()

